CREATE TABLE IF NOT EXISTS gis_phase355_dataset_fingerprint (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), source_a TEXT NOT NULL, source_b TEXT NOT NULL, provider_a TEXT, provider_b TEXT, feature_count_a BIGINT NOT NULL DEFAULT 0, feature_count_b BIGINT NOT NULL DEFAULT 0, shared_feature_keys BIGINT NOT NULL DEFAULT 0, shared_state_keys BIGINT NOT NULL DEFAULT 0, same_geometry_hash BIGINT NOT NULL DEFAULT 0, centroid_near BIGINT NOT NULL DEFAULT 0, area_similar BIGINT NOT NULL DEFAULT 0, fingerprint_status TEXT NOT NULL, evidence JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(source_a,source_b));